/**
 * Subscription Types
 *
 * Type definitions for the billing and subscription module. Defines plan
 * structures, tier hierarchies, feature limits, trial information, and
 * account subscription state used across the billing system.
 *
 * @module billing/subscription/types
 */

import type { SubscriptionTier } from "@shared/types";

// Define Subscription type hierarchy
export type SubscriptionHierarchy = "FREE" | "STARTER" | "PRO" | "ENTERPRISE";

export interface SubscriptionPlan {
  tier: SubscriptionTier;
  name: string;
  description: string;
  monthlyPrice: number;
  yearlyPrice: number;
  maxProjects: number;
  features: string[];
  limits: {
    postsPerMonth: number;
    mediaStorageGB: number;
    teamMembers: number;
    apiRequestsPerDay: number;
    analyticsRetentionDays: number;
  };
}

export interface AccountSubscriptionInfo {
  id: string;
  email: string;
  name: string;
  subscription: SubscriptionTier;
  maxProjects: number;
  currentProjects: number;
  createdAt: Date;
  updatedAt: Date;
  plan: SubscriptionPlan;
  usage: {
    projectsUsed: number;
    projectsRemaining: number;
    utilizationPercent: number;
  };
  isActive: boolean;
  daysRemaining?: number;
  trial: {
    isOnTrial: boolean;
    trialStartDate: Date | null;
    trialEndDate: Date | null;
    trialDaysRemaining: number;
    trialExpired: boolean;
  };
  billing: {
    billingCycle: string;
    autoRenewal: boolean;
    nextBillingDate: Date | null;
    lastBillingDate: Date | null;
    stripeCustomerId?: string;
    stripeSubscriptionId?: string;
  };
}

export interface SubscriptionChangeRequest {
  newTier: SubscriptionTier;
  billingCycle: "monthly" | "yearly";
  effectiveDate?: Date;
  reason?: string;
}

export interface SubscriptionStats {
  totalSubscriptions: number;
  subscriptionsByTier: Record<SubscriptionTier, number>;
  totalRevenue: {
    monthly: number;
    yearly: number;
    total: number;
  };
  conversionRates: {
    basicToPro: number;
    proToEnterprise: number;
    overallUpgrade: number;
  };
  churnRisk: {
    highRisk: number;
    mediumRisk: number;
    lowRisk: number;
  };
  growthMetrics: {
    monthlyGrowthRate: number;
    newSubscriptionsThisMonth: number;
    cancelledSubscriptionsThisMonth: number;
  };
}

export interface BillingEvent {
  id: string;
  accountId: string;
  type:
    | "UPGRADE"
    | "DOWNGRADE"
    | "RENEWAL"
    | "CANCELLATION"
    | "SUSPENSION"
    | "REACTIVATION"
    | "TRIAL_START"
    | "TRIAL_END"
    | "AUTO_RENEWAL";
  fromTier?: SubscriptionTier;
  toTier?: SubscriptionTier;
  amount?: number;
  currency: string;
  reason?: string;
  processedBy?: string;
  timestamp: Date;
  metadata?: Record<string, unknown>;
}

export interface TrialInfo {
  isOnTrial: boolean;
  trialStartDate: Date | null;
  trialEndDate: Date | null;
  trialDaysRemaining: number;
  trialExpired: boolean;
}

export interface StartTrialRequest {
  accountId: string;
  tier?: SubscriptionTier;
  trialDurationDays?: number;
  autoRenewal?: boolean;
  billingCycle?: "monthly" | "yearly";
}

// Subscription plan definitions
export const SUBSCRIPTION_PLANS: Record<SubscriptionTier, SubscriptionPlan> = {
  BASIC: {
    tier: "BASIC",
    name: "Basic Plan",
    description: "Perfect for individuals and small projects",
    monthlyPrice: 9.99,
